10	const PAGE_SIZE = 30;
11	
12	export async function GET(req: NextRequest) {
13	  const session = await getSession();
14	  if (!session || (!session.isJvto && session.role !== "ADMIN")) {
15	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
16	  }
17	
18	  const { searchParams } = new URL(req.url);
19	  const rawPhone = searchParams.get("phone");
20	  const page = Math.max(1, parseInt(searchParams.get("page") ?? "1", 10));
21	
22	  if (!rawPhone) return NextResponse.json({ error: "phone required" }, { status: 400 });
23	
24	  const phone = normalizePhone(rawPhone);
25	
26	  const [messages, total] = await Promise.all([
27	    db.messageLog.findMany({
28	      where: { toFrom: phone },
29	      orderBy: { createdAt: "asc" },
30	      skip: (page - 1) * PAGE_SIZE,
31	      take: PAGE_SIZE,
32	      select: {
33	        id: true,
34	        direction: true,
35	        toFrom: true,
36	        content: true,
37	        mediaType: true,
38	        mediaData: true,
39	        createdAt: true,
40	        number: { select: { id: true, label: true, phoneNumber: true } },
41	      },
42	    }),
43	    db.messageLog.count({ where: { toFrom: phone } }),
44	  ]);
45	
46	  return NextResponse.json({
47	    messages,
48	    pagination: {
49	      page,
50	      pageSize: PAGE_SIZE,
51	      total,
52	      totalPages: Math.ceil(total / PAGE_SIZE),
53	    },
54	  });
55	}
