28	/**
29	 * Download and decrypt a WhatsApp media message, save to disk.
30	 * Returns the saved file path (relative to getMediaDir()), or null on failure.
31	 */
32	async function downloadAndSaveMedia(
33	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
34	  fullMsg: any,
35	  messageId: string
36	): Promise<string | null> {
37	  try {
38	    const msgContent = fullMsg.message as Record<string, unknown>;
39	    const msgType = Object.keys(msgContent)[0];
40	    const mediaTypes = ["imageMessage", "videoMessage", "audioMessage", "documentMessage", "stickerMessage"];
41	    if (!mediaTypes.includes(msgType)) return null;
42	
43	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
44	    const msgInner = msgContent[msgType] as Record<string, any>;
45	    const mimetype: string = msgInner?.mimetype ?? "application/octet-stream";
46	    const ext = mimetype.split(";")[0]?.split("/")[1] ?? extensionForMediaMessage(msgContent as Parameters<typeof extensionForMediaMessage>[0]);
47	    if (!ext) return null;
48	
49	    const buffer = await downloadMediaMessage(fullMsg, "buffer", {});
50	    if (!buffer || !(buffer instanceof Buffer)) return null;
51	
52	    const mediaDir = getMediaDir();
53	    fs.mkdirSync(mediaDir, { recursive: true });
54	    const filename = `${messageId}.${ext}`;
55	    fs.writeFileSync(path.join(mediaDir, filename), buffer);
56	    return filename;
57	  } catch {
58	    return null;
59	  }
60	}
