71	function extractMessagePayload(key: any, timestamp: unknown, msgType: string, msgObj: Record<string, unknown>) {
72	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
73	  const m = (msgObj[msgType] ?? {}) as Record<string, any>;
74	
