76	  let media: Record<string, unknown> | null = null;
77	  let location: Record<string, unknown> | null = null;
78	  let contact: Record<string, unknown> | null = null;
79	
80	  switch (msgType) {
81	    case "conversation":
82	      text = msgObj.conversation as string;
83	      break;
84	    case "extendedTextMessage":
85	      text = m.text ?? null;
86	      break;
87	    case "imageMessage":
88	    case "videoMessage":
89	    case "stickerMessage":
90	      text = m.caption ?? null;
91	      media = {
92	        url: m.url ?? null,
93	        mimetype: m.mimetype ?? null,
94	        fileSize: m.fileLength ? Number(m.fileLength) : null,
95	        mediaKey: m.mediaKey ? Buffer.from(m.mediaKey).toString("base64") : null,
96	        directPath: m.directPath ?? null,
97	        ...(msgType === "videoMessage" && { seconds: m.seconds ?? null }),
98	        ...(msgType === "stickerMessage" && { isAnimated: m.isAnimated ?? false }),
99	      };
100	      break;

1	/**
2	 * Phone numbers explicitly whitelisted regardless of country code.
3	 * Stored without + prefix.
4	 */
5	const WHITELISTED_PHONES = new Set([
6	  "6282143403501", // owner test number
7	]);
8	
9	/**
10	 * Returns true if the phone number/JID belongs to a JVTO customer
11	 * (i.e. non-Indonesian, non-group, non-LID).
12	 *
13	 * Skip rules:
14	 *  - WhatsApp groups  (@g.us)
15	 *  - LID format       (@lid) — random internal Meta ID, not a real phone number
16	 *  - Indonesian numbers: 62xxx / +62xxx / 08xxx
17	 *    (unless in WHITELISTED_PHONES)
18	 */
19	export function isJvtoPhone(phoneOrJid: string): boolean {
20	  if (phoneOrJid.includes("@g.us")) return false;
21	  if (phoneOrJid.includes("@lid")) return false;
22	
23	  // Strip everything after @ and leading +
24	  const phone = phoneOrJid.split("@")[0].replace(/^\+/, "");
25	
26	  // Whitelist overrides country-code filter
27	  if (WHITELISTED_PHONES.has(phone)) return true;
28	
29	  if (phone.startsWith("62")) return false;
30	  if (phone.startsWith("08")) return false;
31	
32	  return true;
33	}
34	
35	/** Normalize JID / phone to a plain phone number string (digits only, no + no @). */
36	export function normalizePhone(phoneOrJid: string): string {
37	  return phoneOrJid.split("@")[0].replace(/^\+/, "").trim();
38	}
