1	/**
2	 * JVTO CRM local data — per customer.
3	 * Stores pipeline, labels, notes, reminders linked by jvtoCustomerId.
4	 * GET  /api/jvto/crm/:customerId
5	 * PATCH /api/jvto/crm/:customerId   { pipelineStageId?, labelIds?, notes? }
6	 */
7	import { NextRequest, NextResponse } from "next/server";
8	import { getSession } from "@/lib/auth";
9	import { db } from "@/lib/db";
10	
11	async function requireJvto(session: { isJvto: boolean; role: string } | null) {
12	  if (!session) return false;
13	  return session.isJvto || session.role === "ADMIN";
14	}
15	
16	export async function GET(
17	  _req: NextRequest,
18	  { params }: { params: Promise<{ customerId: string }> }
19	) {
20	  const session = await getSession();
21	  if (!await requireJvto(session)) {
22	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
23	  }
24	
25	  const { customerId } = await params;
26	
27	  let crm = await db.jvtoCrmContact.findUnique({
28	    where: { jvtoCustomerId: customerId },
29	    include: {
30	      labels: true,
31	      adminNotes: { orderBy: { createdAt: "desc" } },
32	      reminders: { orderBy: { dueDate: "asc" } },
33	      pipelineStage: { select: { id: true, name: true, color: true } },
34	    },
35	  });
36	
37	  if (!crm) {
38	    // Auto-create on first access
39	    crm = await db.jvtoCrmContact.create({
40	      data: { jvtoCustomerId: customerId },
41	      include: {
42	        labels: true,
43	        adminNotes: { orderBy: { createdAt: "desc" } },
44	        reminders: { orderBy: { dueDate: "asc" } },
45	        pipelineStage: { select: { id: true, name: true, color: true } },
46	      },
47	    });
48	  }
49	
50	  return NextResponse.json(crm);
51	}
