53	export async function PATCH(
54	  req: NextRequest,
55	  { params }: { params: Promise<{ customerId: string }> }
56	) {
57	  const session = await getSession();
58	  if (!await requireJvto(session)) {
59	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
60	  }
61	
62	  const { customerId } = await params;
63	  const { pipelineStageId, labelIds, notes } = await req.json();
64	
65	  const updated = await db.jvtoCrmContact.upsert({
66	    where: { jvtoCustomerId: customerId },
67	    create: {
68	      jvtoCustomerId: customerId,
69	      ...(notes !== undefined ? { notes } : {}),
70	      ...(pipelineStageId !== undefined ? { pipelineStageId: pipelineStageId || null } : {}),
71	      ...(labelIds ? { labels: { connect: labelIds.map((id: string) => ({ id })) } } : {}),
72	    },
73	    update: {
74	      ...(notes !== undefined ? { notes } : {}),
75	      ...(pipelineStageId !== undefined ? { pipelineStageId: pipelineStageId || null } : {}),
76	      ...(labelIds ? { labels: { set: labelIds.map((id: string) => ({ id })) } } : {}),
77	    },
78	    include: {
79	      labels: true,
80	      pipelineStage: { select: { id: true, name: true, color: true } },
81	    },
82	  });
83	
84	  return NextResponse.json(updated);
85	}
