277	  async connect() {
278	    if (this.status === "connecting" || this.status === "connected") return;
279	    this.status = "connecting";
280	    this.emit("status", { status: "connecting" });
281	
282	    const logger = pino({ level: "silent" });
283	    const authPath = getAuthPath(this.authDirRelative);
284	    fs.mkdirSync(authPath, { recursive: true });
285	
286	    const { state, saveCreds } = await useMultiFileAuthState(authPath);
287	    const { version } = await fetchLatestBaileysVersion();
288	
289	    const sock = makeWASocket({
290	      version,
291	      auth: {
292	        creds: state.creds,
293	        keys: makeCacheableSignalKeyStore(state.keys, logger),
294	      },
295	      printQRInTerminal: false,
296	      logger,
297	      browser: ["WA Dashboard", "Chrome", "1.0.0"],
298	    });
299	
300	    this.sock = sock;
301	    sock.ev.on("creds.update", async () => {
302	      await saveCreds();
303	      void this._backupAuthStateToDb();
304	    });
305	
306	    sock.ev.on(
307	      "connection.update",
308	      async (update: {
309	        connection?: string;
310	        lastDisconnect?: { error?: unknown };
311	        qr?: string;
312	      }) => {
313	        const { connection, lastDisconnect, qr } = update;
314	
315	        if (qr) {
316	          try {
317	            this.qrDataUrl = await QRCode.toDataURL(qr, {
318	              width: 300,
319	              margin: 2,
320	              color: { dark: "#000000", light: "#ffffff" },
321	            });
322	            this.emit("qr", { qr: this.qrDataUrl });
323	          } catch (err) {
324	            console.error("QR generation error:", err);
325	          }
326	        }
327	
328	        if (connection === "close") {
329	          const statusCode = (lastDisconnect?.error as Boom)?.output
330	            ?.statusCode;
331	          const shouldReconnect =
332	            statusCode !== DisconnectReason.loggedOut &&
333	            statusCode !== DisconnectReason.forbidden;
334	
335	          this._stopHeartbeat();
336	          this.status = "disconnected";
337	          this.qrDataUrl = null;
338	          this.user = null;
339	          this.sock = null;
340	
341	          if (shouldReconnect) {
342	            // Brief disconnect during auto-reconnect — delay the UI update by 6s.
343	            // If connection comes back within 6s, the UI never sees "disconnected".
344	            this._disconnectDebounce = setTimeout(() => {
345	              this._disconnectDebounce = null;
346	              if (this.status === "disconnected") {
347	                this.emit("status", { status: "disconnected" });
348	              }
349	            }, 6000);
350	            setTimeout(() => this.connect(), 3000);
351	          } else {
352	            // Permanent disconnect (loggedOut / forbidden) — notify UI immediately.
353	            if (this._disconnectDebounce) {
354	              clearTimeout(this._disconnectDebounce);
355	              this._disconnectDebounce = null;
356	            }
357	            this.emit("status", { status: "disconnected" });
358	          }
359	        }
360	
361	        if (connection === "open") {
362	          // Cancel any pending "disconnected" UI notification — reconnect succeeded.
363	          if (this._disconnectDebounce) {
364	            clearTimeout(this._disconnectDebounce);
365	            this._disconnectDebounce = null;
366	          }
367	          this._startHeartbeat();
368	          this.status = "connected";
369	          this.qrDataUrl = null;
370	          const me = sock.user;
371	          this.user = me ? { id: me.id, name: me.name ?? me.id } : null;
372	
373	          // Persist phone number to DB
374	          if (this.user && this.numberId !== "legacy") {
375	            try {
376	              const { db } = await import("./db");
377	              const phoneNumber =
378	                this.user.id.split(":")[0]?.split("@")[0] ?? null;
379	              await db.waNumber.update({
380	                where: { id: this.numberId },
381	                data: { phoneNumber },
382	              });
383	            } catch {
384	              // non-fatal
385	            }
386	          }
387	
388	          this.emit("connected", { user: this.user });
389	          this.emit("status", { status: "connected", user: this.user });
390	        }
391	      }
392	    );
393	
394	    sock.ev.on(
395	      "messages.upsert",
396	      async ({ messages, type }: { messages: unknown[]; type: string }) => {
397	        if (type !== "notify") return;
398	        for (const msg of messages as {
399	          message?: unknown;
400	          key: {
401	            remoteJid?: string | null;
402	            fromMe?: boolean;
403	            id?: string;
404	          };
405	          messageTimestamp?: unknown;
406	        }[]) {
407	          if (!msg.message) continue;
408	          if (isJidBroadcast(msg.key.remoteJid ?? "")) continue;
409	
410	          this.stats.received++;
411	
412	          const msgObj = msg.message as Record<string, unknown>;
413	          const msgType = Object.keys(msgObj)[0];
414	          const payload = extractMessagePayload(msg.key, msg.messageTimestamp, msgType, msgObj);
415	
416	          this.emit("message", { message: payload });
417	          this.emit("stats", { stats: this.stats });
418	
419	          if (this.webhookUrl) {
420	            this._sendWebhook(payload).catch(() => {});
421	          }
422	
423	          // Save to MessageLog only for JVTO customers (non-Indonesian, non-group)
424	          const remoteJid = msg.key.remoteJid ?? "";
425	
426	          // Resolve @lid to real phone via Baileys key.remoteJidAlt
427	          let resolvedPhone: string | null = null;
428	          if (remoteJid.includes("@lid")) {
429	            // eslint-disable-next-line @typescript-eslint/no-explicit-any
430	            const remoteJidAlt = (msg.key as any).remoteJidAlt ?? null;
431	            if (remoteJidAlt && !remoteJidAlt.includes("@lid")) {
432	              const altPhone = normalizePhone(remoteJidAlt);
433	              if (isJvtoPhone(altPhone)) {
434	                resolvedPhone = altPhone;
435	              }
436	            }
437	          } else if (isJvtoPhone(remoteJid)) {
438	            resolvedPhone = normalizePhone(remoteJid);
439	          }
440	
